local config = {
  ui_story_31730401_1_dialog_content = "Semua tamu perjamuan telah diperhitungkan.",
  ui_story_31730401_2_dialog_content = "Perangkat hiburan di setiap kamar tamu juga diperiksa.",
  ui_story_31730401_3_dialog_content = "Setiap kamar telah diisi dengan 23 jenis kue yang berbeda, serta 86 jenis teh yang berbeda.",
  ui_story_31730401_4_dialog_content = "Petunjuk ke ruang perjamuan juga telah dipasang di pintu setiap kamar.",
  ui_story_31730401_5_dialog_content = "Keamanan telah selesai melakukan inspeksi keselamatan menyeluruh.",
  ui_story_31730401_6_dialog_content = "Tuan dan Nona Nina seharusnya sedang tidur siang saat ini...",
  ui_story_31730401_7_dialog_content = "Yang berarti saya sekarang memiliki kesempatan sempurna untuk membasmi mereka yang telah berbuat salah pada keluarga Andersen.",
  ui_story_31730401_8_dialog_content = "Ini seharusnya jalan. Dari sana, belok kiri di persimpangan pertama, lalu berjalan empat pintu ke bawah, gedung kedua di sisi barat.",
  ui_story_31730401_9_dialog_content = "Itu adalah <color=#FFB400>Abu-abu</color> tempat tinggal. Saya menerima permintaan pekerjaan dari <color=#FFB400>poros baja</color> sana beberapa hari yang lalu.",
  ui_story_31730401_10_dialog_content = "Rupanya, Gray salah satu dari Steelshafts yang berencana untuk <color=#FFB400>menyerbu Rumah Andersen</color> pada malam Androma Andersen membuat pengumumannya.",
  ui_story_31730401_11_dialog_content = "Sejauh yang saya tahu, Steelshafts tidak memiliki banyak di barisan mereka, jadi mereka mengandalkan kelicikan untuk mengalahkan musuh mereka.",
  ui_story_31730401_12_dialog_content = "Meskipun waktu ada di pihak Anda, saya sarankan Anda berhati-hati dengan rencana mereka sebelum mengambil langkah.",
  ui_story_31730401_13_dialog_content = "Anda memiliki rasa terima kasih saya yang tulus, Tuan Nekoyashiki.",
  ui_story_31730401_14_dialog_content = "* Batuk * uh ... formalitas tidak diperlukan.",
  ui_story_31730401_15_dialog_content = "Ini adalah tempatnya.",
  ui_story_31730401_16_dialog_content = "*Batuk*... Tampaknya tidak peduli berapa kali saya datang ke sini, saya tidak pernah bisa terbiasa dengan debu di udara.",
  ui_story_31730401_17_dialog_content = "Tuan Gray?",
  ui_story_31730401_18_dialog_content = "Ngh...",
  ui_story_31730401_19_dialog_content = "Minuman keras! Lebih banyak minuman keras...",
  ui_story_31730401_20_dialog_content = "\"Minuman keras\"? Saya akan dengan senang hati menuangkan minuman untuk Anda, Pak. Tapi maukah Anda membuka pintu terlebih dahulu?",
  ui_story_31730401_21_dialog_content = "Membanting!",
  ui_story_31730401_22_dialog_content = "Apa...? Mana minumannya?! Ngh... Tidak ada minuman keras?!",
  ui_story_31730401_23_dialog_content = "Beraninya kau berbohong padaku! Saya dengan Steelshafts, tidak tahu ?!",
  ui_story_31730401_24_dialog_content = "Tuan Gray, tolong buka matamu lebar-lebar dan perhatikan baik-baik siapa aku.",
  ui_story_31730401_25_dialog_content = "Aku tidak peduli siapa kamu—",
  ui_story_31730401_X25_dialog_content = "Ah!",
  ui_story_31730401_X26_dialog_content = "Aku tidak memintamu untuk berlutut, Tn. Gray.",
  ui_story_31730401_26_dialog_content = "S-Tuan!",
  ui_story_31730401_27_dialog_content = "Anda di sini, Pak!",
  ui_story_31730401_28_dialog_content = "Aku mohon padamu! Beri aku dua hari lagi—tidak, satu! Aku akan mengurusnya malam ini, aku bersumpah!",
  ui_story_31730401_29_dialog_content = "Aku akan punya lebih banyak uang malam ini! Saya hanya perlu sedikit waktu lagi, dan saya dapat membayar Anda kembali secara penuh, dengan bunga!",
  ui_story_31730401_X29_dialog_content = "Silahkan! Aku mengatakan yang sebenarnya, aku bersumpah!",
  ui_story_31730401_30_dialog_content = "Dan aku yakin begitu, Tn. Gray.",
  ui_story_31730401_31_dialog_content = "Tapi melihatmu menangis dan menggeliat di lantai... sungguh tidak pantas.",
  ui_story_31730401_32_dialog_content = "Belum lagi, air matamu telah menodai sepatu kulitku...",
  ui_story_31730401_33_dialog_content = "Ah, tapi tolong jangan khawatir tentang itu.",
  ui_story_31730401_34_dialog_content = "Argh!",
  ui_story_31730401_35_dialog_content = "Punggung Anda menjadi kain pembersih yang bagus.",
  ui_story_31730401_36_dialog_content = "Malam ini... malam ini, Pak! Saya berjanji!",
  ui_story_31730401_37_dialog_content = "Sst... Dengarkan saja, Tn. Gray.",
  ui_story_31730401_38_dialog_content = "Sebagai pemasok minuman keras terbaik Umbraton, jaringan informan saya yang luas adalah satu-satunya hal yang lebih luas daripada pengetahuan saya tentang minuman.",
  ui_story_31730401_39_dialog_content = "Aku sangat menyadari rencanamu untuk menyerang Andersen Mansion malam ini.",
  ui_story_31730401_40_dialog_content = "Tapi sebelum melakukannya, pasti kamu akan berkumpul dengan Steelshafts lainnya di suatu tempat, ya?",
  ui_story_31730401_41_dialog_content = "Biar kutebak... Seseorang di Steelshafts telah memberimu lokasi pertemuan untuk operasi ini, ya?",
  ui_story_31730401_42_dialog_content = "Pak, saya tidak yakin saya mengerti.",
  ui_story_31730401_43_dialog_content = "Tatap mataku saat aku berbicara denganmu, Tn. Gray.",
  ui_story_31730401_44_dialog_content = "Yang perlu Anda lakukan adalah memberi saya lokasinya, dan saya akan merobek slip pinjaman Anda di sini dan sekarang.",
  ui_story_31730401_45_dialog_content = "T-Tapi jika aku melakukan itu, Steelshafts akan mengejar kepalaku—!",
  ui_story_31730401_46_dialog_content = "Saya selalu bisa menggunakan hukuman yang tertulis di kontrak Anda, bukan?",
  ui_story_31730401_47_dialog_content = "Meskipun saya berpikir bahwa kematian cepat akan jauh lebih dapat diterima, tidakkah Anda setuju?",
  ui_story_31730401_48_dialog_content = "T-Tolong, Pak, hanya satu malam lagi...",
  ui_story_31730401_49_dialog_content = "Anda salah paham, Tn. Gray.",
  ui_story_31730401_50_dialog_content = "Anda memiliki tepat tiga detik untuk memberi saya informasi yang saya butuhkan.",
  ui_story_31730401_51_dialog_content = "Tiga-",
  ui_story_31730401_52_dialog_content = "O-Oke! Aku akan bicara!",
  ui_story_31730401_53_dialog_content = "Aku akan bicara...",
  ui_story_31730401_54_dialog_content = "Steelshafts akan berkumpul di dekat reruntuhan Maida Mesa, di sebuah rumah kosong dengan tiga pohon bengkok ditanam di halaman.",
  ui_story_31730401_55_dialog_content = "Saya mengerti. Terima kasih atas kerja sama Anda yang ramah.",
  ui_story_31730401_56_dialog_content = "T-Tunggu, aku tidak mengerti...",
  ui_story_31730401_57_dialog_content = "Mengapa Anda menginginkan informasi ini alih-alih uang yang saya berutang kepada Anda?",
  ui_story_31730401_58_dialog_content = "Kamu muncul entah dari mana sebulan yang lalu dengan maksud untuk menjual roh langka dan mahal kepadaku...",
  ui_story_31730401_59_dialog_content = "Jadi kenapa...",
  ui_story_31730401_60_dialog_content = "Tidak... K-Kamu... Kamu!",
  ui_story_31730401_61_dialog_content = "Anda tahu Steelshafts telah mempekerjakan saya, bukan?",
  ui_story_31730401_62_dialog_content = "Minuman keras, hutang gila, dan sekarang kunjungan ini...",
  ui_story_31730401_63_dialog_content = "Anda melakukan semua itu hanya agar Anda bisa mengetahui tempat berkumpulnya mereka!",
  ui_story_31730401_64_dialog_content = "Anda salah paham, Tn. Gray.",
  ui_story_31730401_65_dialog_content = "Saya memperoleh lokasi mereka sejak lama. Saya hanya datang ke sini untuk mengkonfirmasinya.",
  ui_story_31730401_66_dialog_content = "Sekarang, silakan duduk dan istirahat sebentar.",
  ui_story_31730401_67_dialog_content = "Aku harus mengobrak-abrik lemari pakaianmu untuk kostum yang cocok, jika kau tidak keberatan...",
  ui_story_31730401_68_dialog_content = "Hmm, ini akan berhasil.",
  ui_story_31730401_69_dialog_content = "Hai! Anda baru di sekitar sini?",
  ui_story_31730401_70_dialog_content = "Ya.",
  ui_story_31730401_71_dialog_content = "Sudahkah Anda mengkonfirmasi identitasnya? Dan apakah dia mendapatkan sinyal rahasia dengan benar?",
  ui_story_31730401_72_dialog_content = "Iya Bos! Dia mendapatkan segalanya dengan benar!",
  ui_story_31730401_73_dialog_content = "Hah. Siapa namamu lagi? Abu-abu, bukan?",
  ui_story_31730401_74_dialog_content = "Ya.",
  ui_story_31730401_75_dialog_content = "Anda lebih tinggi dari yang saya harapkan, tapi saya rasa itu tidak masalah.",
  ui_story_31730401_76_dialog_content = "Apakah semua orang di sini belum?",
  ui_story_31730401_77_dialog_content = "Siap, Bos!",
  ui_story_31730401_78_dialog_content = "Baiklah, kalian semua, dengarkan! Sudah waktunya bagi saya untuk mengungkap rencana kami.",
  ui_story_31730401_79_dialog_content = "Saya hanya mengatakannya sekali, jadi dengarkan baik-baik! Setelah saya selesai berbicara, kita akan mengambil semua barang selundupan di sini dan menuju ke titik pertemuan berikutnya!",
  ui_story_31730401_80_dialog_content = "Saya memiliki beberapa pakaian yang dibuat khusus agar terlihat seperti yang dikenakan oleh pelayan keluarga Andersen. Kami akan memakainya sebagai penyamaran untuk masuk.",
  ui_story_31730401_81_dialog_content = "Dan ingat, target kita malam ini adalah Nina Andersen, dan Nina Andersen saja!",
  ui_story_31730401_82_dialog_content = "Jangan terganggu oleh omong kosong mahal yang ada di sekitar Andersen Mansion! Setelah kita mendapatkan sandera kita, pergi dari sana!",
  ui_story_31730401_X82_dialog_content = "Dan jika ada di antara Anda yang membuat kesalahan sekecil apa pun... Nah, Anda tahu apa yang akan terjadi pada Anda.",
  ui_story_31730401_X83_dialog_content = "Saya tidak menyia-nyiakan tahun-tahun ini di Umbraton dengan sia-sia.",
  ui_story_31730401_83_dialog_content = "Dengan putri tercinta Androma dalam tahanan kami, saya yakin dia akan membayar harga berapa pun untuk mendapatkannya kembali.",
  ui_story_31730401_84_dialog_content = "Kami akan membahas infiltrasi dan peran khusus semua orang di titik pertemuan berikutnya.",
  ui_story_31730401_85_dialog_content = "Apakah saya membuat diri saya jelas, anak-anak? Jika demikian, ambil sebanyak mungkin barang selundupan ini dan pindah!",
  ui_story_31730401_86_dialog_content = "Hmm, benar-benar jernih.",
  ui_story_31730401_87_dialog_content = "Saya harus mengatakan...",
  ui_story_31730401_88_dialog_content = "Jika saya tahu betapa sederhana dan bodohnya rencana Anda sejak awal, saya tidak akan pernah secara pribadi datang ke sini.",
  ui_story_31730401_89_dialog_content = "Hah? Apa yang kau bicarakan, Gray?",
  ui_story_31730401_90_dialog_content = "Nah, Anda lihat ...",
  ui_story_31730401_91_dialog_content = "Saya bukan Tuan Gray, melainkan, saya Minos, kepala pelayan eksklusif keluarga Andersen.",
  ui_story_31730401_92_dialog_content = "Sejujurnya, bahkan menyebut nama keluarga Andersen di tempat jorok seperti itu adalah penghinaan yang tidak tahu malu terhadap nama baik Guru.",
  ui_story_31730401_93_dialog_content = "Sial!",
  ui_story_31730401_94_dialog_content = "Tangkap dia, bodoh! Apapun yang terjadi, kita tidak bisa membiarkan orang ini pergi dari sini hidup-hidup!",
  ui_story_31730401_95_dialog_content = "Rasakan ini!",
  ui_story_31730401_96_dialog_content = "Pukulanmu sangat kurang anggun.",
  ui_story_31730401_97_dialog_content = "Menyingkirlah, teman-teman! Aku melepaskan pembakar!",
  ui_story_31730401_98_dialog_content = "Dan Anda, tujuan Anda cukup menyedihkan. Lain kali, memperbaiki gaya rambut Anda yang mengerikan sebelum memotret mungkin bisa sedikit membantu.",
  ui_story_31730401_99_dialog_content = "Sialan kau... Aku akan menggunakan pedangku saja! Aku akan memotongmu!!",
  ui_story_31730401_100_dialog_content = "Ah, maafkan saya, tapi apa yang akan saya katakan mungkin melukai harga diri Anda.",
  ui_story_31730401_101_dialog_content = "Ilmu pedangmu bahkan tidak bisa dibandingkan dengan putri tuanku. Bahkan PlayerName tidak akan kesulitan mengalahkanmu.",
  ui_story_31730401_X101_dialog_content = "Anda banyak yang tidak berguna!",
  ui_story_31730401_102_dialog_content = "Lupakan dia! Ambil saja barangnya dan pergi!",
  ui_story_31730401_103_dialog_content = "Untung aku datang siap. Saya satu-satunya yang tahu persis di mana titik pertemuan berikutnya!",
  ui_story_31730401_104_dialog_content = "Enam di atap, sepuluh di luar rumah, dan... lima belas di dalam rumah.",
  ui_story_31730401_105_dialog_content = "Seperti yang saya prediksi, kurang lebih.",
  ui_story_31730401_106_dialog_content = "Kalau begitu... Aku yakin sudah waktunya untuk mengakhiri permainan kecil ini.",
  ui_story_31730401_107_dialog_content = "Dengan acara penting yang harus saya hadiri malam ini, saya benar-benar ingin menghindari mengotori tangan saya dengan bau busuk...",
  ui_story_31730401_108_dialog_content = "Tapi karena hama biasanya bergegas pergi, saya kira saya harus menyelesaikan ini dengan cepat dan menghilangkan bau busuk ketika saya kembali.",
  ui_story_31730401_109_dialog_content = "Kemudian lagi, sebagai kepala pelayan yang bangga, saya selalu senang membersihkan semuanya.",
  ui_story_31730401_110_dialog_content = "Jadi tolong, jangan takut... Aku sebenarnya cukup lembut.",
  ui_story_31730401_111_dialog_content = "Langkah pertama dalam memelihara rumah yang rapi dan rapi—",
  ui_story_31730401_112_dialog_content = "—adalah untuk mengumpulkan semua sampah dan membuangnya dengan benar.",
  ui_story_31730401_113_dialog_content = "Salam pembuka, PlayerName, dan selamat datang lagi di rumah tuanku.",
  ui_story_31730401_114_dialog_content = "Apakah Anda cukup istirahat di kamar Anda? Apakah minuman dan perangkat hiburan sesuai dengan keinginan Anda?",
  ui_story_31730401_115_option_content = "Sangat cocok!",
  ui_story_31730401_116_dialog_content = "Hanya jawaban yang ingin saya dengar.",
  ui_story_31730401_117_dialog_content = "Eh, Mino...? Apakah kamu baik - baik saja? Anda tidak terlihat sangat baik ...",
  ui_story_31730401_118_option_content = "Ya, tapi...",
  ui_story_31730401_119_dialog_content = "Kamu terlihat lelah, Minos.",
  ui_story_31730401_120_dialog_content = "Kamu pasti sangat sibuk hari ini.",
  ui_story_31730401_121_dialog_content = "Tidak ada sama sekali.",
  ui_story_31730401_122_dialog_content = "Saya minta maaf jika penampilan saya membuat Anda khawatir.",
  ui_story_31730401_123_dialog_content = "Mengkhawatirkan tamu kami yang terhormat adalah salah satu hal terburuk yang bisa dilakukan kepala pelayan.",
  ui_story_31730401_124_dialog_content = "Mungkin saya harus menggunakan beberapa kosmetik wanita untuk mencerahkan penampilan saya?",
  ui_story_31730401_125_dialog_content = "Aku tidak tahu kau punya, um... kesombongan, Minos.",
  ui_story_31730401_126_dialog_content = "Ah, aku hanya bercanda.",
  ui_story_31730401_127_dialog_content = "Sekarang, Tuan Navigator, silakan pergi ke ruang perjamuan dan nikmati makanan Anda.",
  ui_story_31730401_128_dialog_content = "Sayangnya, saya masih memiliki hal-hal lain untuk diperhatikan.",
  ui_story_31730401_129_dialog_content = "Sebelum pesta dimulai dengan sungguh-sungguh, saya harus membuat laporan mendesak kepada tuan saya.",
  ui_story_31730401_130_dialog_content = "Jika Anda membutuhkan sesuatu, jangan ragu untuk bertanya kepada salah satu pelayan. Saya akan bergabung kembali dengan Anda dan yang lainnya sebentar lagi.",
  ui_story_31730401_131_dialog_content = "Tentu, aku bisa menjaga diriku sendiri, jangan khawatir.",
  ui_story_31730401_132_dialog_content = "Merupakan kehormatan besar bagi saya untuk memiliki Anda semua sebagai tamu di rumah saya malam ini.",
  ui_story_31730401_133_dialog_content = "Seperti yang kemungkinan besar sudah Anda dengar sekarang, ya... Ada pengumuman kecil yang harus saya sampaikan.",
  ui_story_31730401_134_dialog_content = "Tidak ada yang menghancurkan bumi, dengan cara apa pun. Sebaliknya, itu hanyalah penegasan arah baru di mana keluarga Andersen akan tumbuh.",
  ui_story_31730401_135_dialog_content = "Hadirin sekalian, dengan senang hati saya mengumumkan—",
  ui_story_31730401_136_dialog_content = "Mulai hari ini, keluarga Andersen secara resmi akan memasuki industri real estat!",
  ui_story_31730401_137_dialog_content = "Selamat! Selamat, Androma!",
  ui_story_31730401_138_dialog_content = "Apakah ini kekuatan bangsawan tua?",
  ui_story_31730401_139_dialog_content = "Tampaknya setiap kamar tamu telah diisi dengan segala macam minuman dan fasilitas rekreasi... Jika saya tidak tahu lebih baik, saya akan mengatakan kami masih di Lumopolis!",
  ui_story_31730401_140_dialog_content = "Dan dengan pengumuman kecil ini, saya meminta Anda untuk menikmati semua yang ditawarkan perjamuan kami.",
  ui_story_31730401_141_dialog_content = "Apa itu tadi? Apakah Anda baru saja mendengarnya?",
  ui_story_31730401_142_dialog_content = "Apakah itu ledakan?",
  ui_story_31730401_143_dialog_content = "Ya, saya yakin saya juga mendengarnya...",
  ui_story_31730401_144_dialog_content = "Jangan mendahului dirimu sendiri! Master Androma kemungkinan besar memesan kembang api untuk malam ini!",
  ui_story_31730401_145_dialog_content = "Nah, haruskah kita pergi keluar dan melihat?",
  ui_story_31730401_146_dialog_content = "Kurasa kita harus... Lagi pula, itu memang terdengar seperti kembang api.",
  ui_story_31730401_147_dialog_content = "Apakah semua selundupan telah diurus?",
  ui_story_31730401_148_dialog_content = "Siap, Master.",
  ui_story_31730401_149_dialog_content = "Saya telah mengatur seseorang untuk menyalakan kembang api. Nona Nina juga cukup ngotot melihat mereka.",
  ui_story_31730401_150_dialog_content = "Saya mengerti. Bagus, Minos.",
  ui_story_31730401_151_dialog_content = "Oh, dan anggur yang Anda sediakan untuk kami hari ini benar-benar nikmat.",
  ui_story_31730401_152_dialog_content = "Betapa murah hati Anda mengatakan demikian, Guru... Tapi ini semua adalah bagian dari tugas saya sebagai kepala pelayan Anda yang rendah hati.",
  ui_story_31730401_153_dialog_content = "Hati-hati, Bu Nina. Jangan terlalu lama di luar, nanti kamu masuk angin!",
  ui_story_31730401_154_dialog_content = "Aku tahu, aku tahu!",
  ui_story_31730401_155_dialog_content = "Oh, dan Minos?",
  ui_story_31730401_156_dialog_content = "Kapan rumah hantu itu siap? Saya membeli segala macam alat peraga untuk itu!",
  ui_story_31730401_157_dialog_content = "Segera, Bu.",
  ui_story_31730401_158_dialog_content = "Percayalah—maksudku, segera.",
  ui_story_31730601_2_dialog_content = "Tidak—!",
  ui_story_31730601_3_dialog_content = "Saya telah berbelanja di sini sepanjang waktu. Bagaimana bisa tiba-tiba... tutup...",
  ui_story_31730601_4_dialog_content = "Oh? Bukankah ini Tuan Navigator?",
  ui_story_31730601_5_dialog_content = "Baru saja aku mendengar teriakan dan datang untuk memeriksa. Apakah kamu dalam masalah?",
  ui_story_31730601_6_dialog_content = "Ah... Maaf mengganggumu. Sebenarnya ini bukan masalah besar.",
  ui_story_31730601_7_dialog_content = "Toko tempat saya selalu membeli tiba-tiba tutup, membuat saya bingung harus berbelanja di mana sekarang.",
  ui_story_31730601_8_dialog_content = "Bisnis di Umbraton datang dan pergi sepanjang waktu. Mereka sering harus menutup toko karena satu alasan atau lainnya.",
  ui_story_31730601_9_dialog_content = "Oleh karena itu, disarankan untuk kamu tidak mendaftar menjadi anggota, karena ada kemungkinan besar ditipu.",
  ui_story_31730601_10_dialog_content = "... Bukan berarti saya punya cukup uang untuk mendaftar keanggotaan.",
  ui_story_31730601_11_dialog_content = "Apa yang ingin Anda beli?",
  ui_story_31730601_12_dialog_content = "Hmm... Saya ingin membeli kertas pembungkus dan pita untuk persiapan liburan.",
  ui_story_31730601_13_dialog_content = "Oh? Dalam hal itu, kebetulan saya tahu tempat untukmu.",
  ui_story_31730601_14_dialog_content = "Izinkan saya memimpin jalan untukmu.",
  ui_story_31730601_15_dialog_content = "Itu sangat baik dari kamu. Apakah kamu baru saja selesai berbelanja juga? Dengan semua tas di sini...",
  ui_story_31730601_16_dialog_content = "Benar, iya. Saya sudah pergi ke beberapa toko, mencoba memilih barang yang paling hemat biaya.",
  ui_story_31730601_17_dialog_content = "Tolong jangan khawatir. Kami memang sedang dalam perjalanan. Cuaca akhir-akhir ini sangat lembab, jadi saya perlu membeli beberapa dupa pengusir serangga.",
  ui_story_31730601_18_dialog_content = "Kalau tidak... Saya khawatir kamu akan menemukannya lucu. Wanita muda itu mungkin akan membuat ulah lagi.",
  ui_story_31730601_19_dialog_content = "Tidak, tidak... Biar aku bantu sedikit!",
  ui_story_31730601_20_dialog_content = "Terima kasih atas kebaikanmu, kalau begitu.",
  ui_story_31730601_21_dialog_content = "Wow, semua barang di dalam tas sebenarnya sudah disortir?",
  ui_story_31730601_22_dialog_content = "Kamu benar-benar menangani semua hal sebagai kepala pelayan.",
  ui_story_31730601_23_dialog_content = "Hampir seperti kamu dilahirkan untuk menjadi seorang butler. Itu hampir tidak seperti...",
  ui_story_31730601_24_dialog_content = "Maksud kamu seorang pembunuh?",
  ui_story_31730601_25_dialog_content = "Ah, maaf... Aku rasa aku sedikit terbawa suasana...",
  ui_story_31730601_26_dialog_content = "Jangan khawatir, seseorang sudah pernah mengatakan ini tentang saya sebelumnya...",
  ui_story_31730601_27_dialog_content = "Kita masih memiliki perjalanan yang panjang. Ingin mendengar beberapa cerita dari masa laluku?",
  ui_story_31730601_28_dialog_content = "Tentu saja!",
  ui_story_31730601_29_dialog_content = "Mengingat kembali, dialah yang menyelamatkan hidupku...",
  ui_story_31730601_30_dialog_content = "<color=#e8d9bb>Bukk!!</color>",
  ui_story_31730601_31_dialog_content = "Hmph, sungguh kerbau keras kepala untuk dijinakkan...",
  ui_story_31730601_32_dialog_content = "Apakah kaulah yang telah memusnahkan delapan orang anak buahku?",
  ui_story_31730601_33_dialog_content = "Aku datang dengan hadiah dari master, dan beginikah cara kau membalas kebaikannya...?",
  ui_story_31730601_34_dialog_content = "Betapa memalukan. Kalian harus malu menyebut diri kalian sekutu keluarga!",
  ui_story_31730601_35_dialog_content = "Kebaikan hati? Sekutu? Tidak, jika kamu tinggal di sini, kamu harus tahu bahwa kami tidak peduli dengan hal-hal seperti itu.",
  ui_story_31730601_36_dialog_content = "Kekuatan adalah segalanya, kita tidak memerlukan keluarga yang lemah.",
  ui_story_31730601_37_dialog_content = "Beraninya kamu membuat ucapan yang serakah dan tak tahu malu seperti itu?",
  ui_story_31730601_38_dialog_content = "Heh, akan kutunjukkan kepada kalian semua—",
  ui_story_31730601_39_dialog_content = "?!",
  ui_story_31730601_40_dialog_content = "Turunkan dia!",
  ui_story_31730601_41_dialog_content = "D-Jangan biarkan dia mendekati Bos!",
  ui_story_31730601_42_dialog_content = "Pengkhianatan dan penipuan... Itulah kelemahan yang sebenarnya!",
  ui_story_31730601_43_dialog_content = "... Hampir.",
  ui_story_31730601_44_dialog_content = "Begitu kasihan orang bodoh itu. Setiap pembunuh tahu bahwa cara terbaik untuk tetap hidup adalah dengan bergabung dengan pihak yang lebih kuat.",
  ui_story_31730601_45_dialog_content = "Lakukan apa saja yang kamu mau, aku tidak peduli...",
  ui_story_31730601_46_dialog_content = "Aku bukan kamu... Aku tidak akan pernah mengkhianati guru dan wanita muda.",
  ui_story_31730601_47_dialog_content = "Lalu jika aku membawamu ke negosiasi dengan keluarga Andersen...",
  ui_story_31730601_48_dialog_content = ".. dan tunjukkan pada tuanmu betapa menyedihkannya dirimu sekarang?",
  ui_story_31730601_49_dialog_content = "Kenapa kamu...!",
  ui_story_31730601_50_dialog_content = "Bungkam dia, lalu masukkan dia ke dalam kasus yang dia bawa.",
  ui_story_31730601_51_dialog_content = "Ya!",
  ui_story_31730601_52_dialog_content = "Karena keluarga Andersen telah memberiku hadiah, aku harus membalas budi.",
  ui_story_31730601_53_dialog_content = "Binatang! Aku harus membunuhmu... Aku seharusnya... Argh!!!",
  ui_story_31730601_54_dialog_content = "<color=#e8d9bb>Seperti itu, saya dimasukkan ke dalam koper dan diletakkan di kereta kuda.</color>",
  ui_story_31730601_55_dialog_content = "<color=#e8d9bb>Mereka terburu-buru, tetapi mereka berhenti. Mungkin ada kecelakaan atau sesuatu, atau geng lain.</color>",
  ui_story_31730601_56_dialog_content = "<color=#e8d9bb>Saya berjuang untuk merangkak keluar dari kereta tapi tidak bisa membuka koper.</color>",
  ui_story_31730601_57_dialog_content = "<color=#e8d9bb>Kemudian, aku merasakan tangan yang lemah mendorong kasus yang sedang aku hadapi dengan goyah...</color>",
  ui_story_31730601_58_dialog_content = "<color=#e8d9bb>Gedebuk-</color>",
  ui_story_31730601_59_dialog_content = "...",
  ui_story_31730601_60_dialog_content = "Ini bukan uang kotor atau perhiasan dari geng...",
  ui_story_31730601_61_dialog_content = "Aku telah mengecewakanmu, bukan?",
  ui_story_31730601_62_dialog_content = "…!",
  ui_story_31730601_63_dialog_content = "Awalnya kukira itu hanya anak kucing atau anak anjing, tapi... tapi...",
  ui_story_31730601_64_dialog_content = "Dunia adalah hamparan peristiwa tak terduga.",
  ui_story_31730601_65_dialog_content = "Jika Anda tidak ingin mendapatkan masalah, sebaiknya Anda pergi...",
  ui_story_31730601_66_dialog_content = "A... Aku tahu...",
  ui_story_31730601_67_dialog_content = "<color=#e8d9bb>Gruk—</color>",
  ui_story_31730601_68_dialog_content = "…?!",
  ui_story_31730601_69_dialog_content = "Apa yang akan kamu lakukan... Kenapa kamu masih mendorongku?!",
  ui_story_31730601_70_dialog_content = "Kamu akan mati jika aku meninggalkanmu di sini, bukan?",
  ui_story_31730601_71_dialog_content = "Saya tahu tentang rumah sakit bawah tanah yang mengkhususkan diri dalam merawat orang-orang seperti kamu.",
  ui_story_31730601_72_dialog_content = "Aku akan membawamu ke sana, tapi tentang apa yang akan terjadi selanjutnya... Yah, aku benar-benar tidak tahu...",
  ui_story_31730601_73_dialog_content = "Mengetahui siapa aku, kamu masih ingin menyelamatkanku?",
  ui_story_31730601_74_dialog_content = "A-aku tidak suka bau darah pada dirimu...",
  ui_story_31730601_75_dialog_content = "Tapi, meski bau darah begitu kuat, saya masih bisa mencium aroma tepung dan mentega darimu.",
  ui_story_31730601_76_dialog_content = "Gangster asli itu... Mereka berbau pipa, minuman keras murah, dan kasino.",
  ui_story_31730601_77_dialog_content = "Jadi kamu seperti koki atau butler, anak baik yang terjebak dalam kekacauan ini, 'kan?",
  ui_story_31730601_78_dialog_content = "Itu adalah wanita yang tajam.",
  ui_story_31730601_79_dialog_content = "Dan dalam keadaan seperti itu... itu benar-benar mengagumkan.",
  ui_story_31730601_80_dialog_content = "Ah, kita sudah sampai. Ini tempatnya.",
  ui_story_31730601_81_dialog_content = "Ini temanmu, Tuan Muda Butler?",
  ui_story_31730601_82_dialog_content = "Dia adalah teman dekat, dan ini adalah kali pertama dia datang ke sini, jadi apa kamu keberatan memberi kami diskon?",
  ui_story_31730601_83_dialog_content = "Tidak masalah, tentu saja... seorang teman dekat dari Tuan Muda Butler.",
  ui_story_31730601_84_dialog_content = "N-Senang bertemu denganmu.",
  ui_story_31730601_85_dialog_content = "*mengendus*",
  ui_story_31730601_86_dialog_content = "Hah... Apakah aku, apakah aku memiliki bau tertentu di tubuhku?",
  ui_story_31730601_87_dialog_content = "Ah, maaf, penglihatanku tidak terlalu baik, jadi aku cenderung mengingat pelanggan dari aroma mereka.",
  ui_story_31730601_88_dialog_content = "Kamu... Kamu bau seperti langit.",
  ui_story_31730601_89_dialog_content = "Sangat jernih, terang, dan berpikiran maju. Ini adalah hembusan udara segar.",
  ui_story_31730601_90_dialog_content = "Ini sangat cocok dengan aroma mentega dan tepung muda Tuan Butler.",
  ui_story_31730601_91_dialog_content = "Apakah kamu bekerja di Shuttle Hub?",
  ui_story_31730601_92_dialog_content = "Saya memiliki buket dan aromaterapi yang cocok untuk pesawat. Apakah Anda ingin melakukan pembelian?",
  ui_story_31730601_93_dialog_content = "Ya, tolong. Aku memang membutuhkan beberapa dari itu.",
  ui_story_31730601_94_dialog_content = "... Jadi ini wanita yang telah menyelamatkanmu?",
  ui_story_31730601_95_dialog_content = "Ya, bagaimanapun, itu adalah bantuan yang menyelamatkan hidup. Dia membantu saya melarikan diri dan kembali ke keluarga Andersen.",
  ui_story_31730601_96_dialog_content = "Sekarang dia sudah lebih tua, saya sering datang untuk melihatnya.",
  ui_story_31730601_97_dialog_content = "Dan kamu membawaku ke sini...",
  ui_story_31730601_98_option_content = "Agar aku bisa memahamimu lebih baik?",
  ui_story_31730601_99_dialog_content = "Oh, aku tidak menyangka kamu memahami hal-hal dengan cara ini.",
  ui_story_31730601_100_dialog_content = "Tapi dalam satu cara, ya. Masa laluku terikat erat dengan sejarah pembunuhan keluarga.",
  ui_story_31730601_101_dialog_content = "Dan berbagi dengan kamu sesuatu yang belum pernah saya ceritakan kepada siapa pun sebelumnya benar-benar memberi saya rasa lega.",
  ui_story_31730601_102_option_content = "Jadi, saya juga bisa menemaninya?",
  ui_story_31730601_103_dialog_content = "Tentu saja, dia mungkin akan lebih bahagia jika ada lebih banyak orang di sekitarnya.",
  ui_story_31730601_104_dialog_content = "Dan ini juga pertama kalinya saya membawa seseorang yang tahu tentang masalah ini ke tempatnya.",
  ui_story_31730601_105_dialog_content = "Kamu juga telah mengetahui salah satu rahasiaku.",
  ui_story_31730601_106_dialog_content = "Ini akan menjadi kehormatan terbesar saya.",
  ui_story_31730601_107_dialog_content = "Pokoknya, tempat ini sangat indah, silakan pilih sesuka hati di sini.",
  ui_story_31730601_108_dialog_content = "Terima kasih, aku yakin aku akan menemukan sesuatu yang aku suka di sini!"
}
return config
